import{_ as i,c as e,o as s,ag as l}from"./chunks/framework.DfL_BkQ-.js";const g=JSON.parse('{"title":"屏幕录制权限指南（macOS）","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/screen-recording.md","filePath":"zh-CN/guide/screen-recording.md","lastUpdated":1794112334000}'),t={name:"zh-CN/guide/screen-recording.md"};function r(o,a,n,c,p,h){return s(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="屏幕录制权限指南-macos" tabindex="-1">屏幕录制权限指南（macOS） <a class="header-anchor" href="#屏幕录制权限指南-macos" aria-label="Permalink to &quot;屏幕录制权限指南（macOS）&quot;">​</a></h1><h2 id="为什么-nicasa-需要屏幕录制权限" tabindex="-1">为什么 Nicasa 需要屏幕录制权限？ <a class="header-anchor" href="#为什么-nicasa-需要屏幕录制权限" aria-label="Permalink to &quot;为什么 Nicasa 需要屏幕录制权限？&quot;">​</a></h2><p>在 macOS 上，截图与屏幕捕捉类应用必须获得屏幕录制权限，才能读取显示器上的像素。</p><p>从 macOS 10.15 Catalina 开始，Apple 引入了更严格的隐私保护。任何捕捉屏幕内容（包括截图）的应用都必须获得用户的明确授权。</p><p>这适用于所有应用，包括从 Mac App Store 下载的应用。</p><p><strong>没有该权限，Nicasa 无法截图或录制屏幕内容。</strong></p><h2 id="如何开启屏幕录制权限" tabindex="-1">如何开启屏幕录制权限 <a class="header-anchor" href="#如何开启屏幕录制权限" aria-label="Permalink to &quot;如何开启屏幕录制权限&quot;">​</a></h2><p>请按以下步骤操作：</p><ol><li>打开 <strong>系统设置</strong></li><li>进入 <strong>隐私与安全性</strong></li><li>选择 <strong>屏幕录制</strong></li><li>在列表中找到 <strong>Nicasa</strong> 并勾选</li></ol><p>如果应用当时已在运行，请在授予权限后重启 Nicasa。</p><h2 id="如果权限弹窗没有出现" tabindex="-1">如果权限弹窗没有出现 <a class="header-anchor" href="#如果权限弹窗没有出现" aria-label="Permalink to &quot;如果权限弹窗没有出现&quot;">​</a></h2><p>权限对话框通常会在应用首次尝试捕捉屏幕时出现。</p><p>如果你没有看到该弹窗，可能是因为：</p><ul><li>权限请求此前被拒绝过</li><li>macOS 缓存了权限状态</li><li>应用在弹窗出现之前就执行了捕捉</li></ul><p>这种情况下，你可能需要重置该权限。</p><h2 id="重置屏幕录制权限" tabindex="-1">重置屏幕录制权限 <a class="header-anchor" href="#重置屏幕录制权限" aria-label="Permalink to &quot;重置屏幕录制权限&quot;">​</a></h2><p>你可以在终端中使用以下命令重置权限：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tccutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ScreenCapture</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.nicasa.nue</span></span></code></pre></div><p>执行命令后：</p><ol><li>重启 Nicasa</li><li>再次触发截图功能</li><li>macOS 应会重新弹出权限对话框</li></ol><h2 id="如果重置仍然无效" tabindex="-1">如果重置仍然无效 <a class="header-anchor" href="#如果重置仍然无效" aria-label="Permalink to &quot;如果重置仍然无效&quot;">​</a></h2><p>极少数情况下，macOS 可能会保留无效的权限状态。</p><p>如果重置权限没有解决问题，请尝试以下步骤：</p><ol><li>退出 Nicasa</li><li>从「应用程序」文件夹中删除 Nicasa</li><li>从 Mac App Store 重新安装最新版本</li><li>再次启动应用</li><li>当 macOS 请求屏幕录制权限时，选择 <strong>允许</strong></li></ol><p>重新安装应用可以促使 macOS 重建权限记录。</p><h2 id="另一种手动修复方法" tabindex="-1">另一种手动修复方法 <a class="header-anchor" href="#另一种手动修复方法" aria-label="Permalink to &quot;另一种手动修复方法&quot;">​</a></h2><p>你也可以手动切换一次权限：</p><ol><li>打开 <strong>系统设置</strong></li><li>进入 <strong>隐私与安全性</strong></li><li>打开 <strong>屏幕录制</strong></li><li>取消勾选 Nicasa，然后重新勾选</li><li>重启 Nicasa</li></ol><h2 id="安全说明" tabindex="-1">安全说明 <a class="header-anchor" href="#安全说明" aria-label="Permalink to &quot;安全说明&quot;">​</a></h2><p>授予屏幕录制权限并不会让 Nicasa 控制你的系统。</p><p>它仅允许应用为截图与捕捉功能读取屏幕像素。</p><p>你可以随时在以下位置撤销该权限： <strong>系统设置 → 隐私与安全性 → 屏幕录制</strong></p>',32)])])}const u=i(t,[["render",r]]);export{g as __pageData,u as default};
